<script setup>
import { ref, onMounted } from 'vue'
import { api, user } from '../api'
import Button from '../components/ui/Button.vue'
import DataTable from '../components/ui/DataTable.vue'
import Modal from '../components/ui/Modal.vue'
import Field from '../components/ui/Field.vue'
import TextInput from '../components/ui/TextInput.vue'
import Tag from '../components/ui/Tag.vue'
import Segmented from '../components/ui/Segmented.vue'
import PanoramaGraph from '../components/business/PanoramaGraph.vue'
import { computed } from 'vue'
import { useViewMode } from '../composables/view'
const emit = defineEmits(['saved', 'error'])
const rows = ref([]), permissions = ref(null), loading = ref(false), error = ref(''), open = ref(false), target = ref(null), passwordOpen = ref(false), form = ref({ name: '', username: '', password: '', role: 'staff' }), password = ref(''), busy = ref(false)
const staffView = useViewMode('staff', 'table', ['table', 'panorama'], 'table')
const functions = ['查看客戶', '查看牌照', '查看公司', '辦理工單', '填寫日期', '錄入過關', '上傳文件', '規則設定', '委託範圍', '轉讓牌照', '管理帳號', '收費管理']
const functionCodes = ['customers.read', 'plates.read', 'companies.read', 'requests.manage', 'dates.write', 'crossings.write', 'documents.write']
function canUse(row, name) { return row.role === 'admin' || permissions.value?.roles?.staff?.includes(functionCodes[functions.indexOf(name)]) }
const staffCategories = computed(() => [
  { id: 'staff', label: '員工', ratio: rows.value.length ? rows.value.filter(row => row.active).length / rows.value.length : 0, entries: rows.value.map(row => ({ id: String(row.id), label: row.name, sub: `${row.role === 'admin' ? '管理者' : '員工'} · ${row.last_login_at?.slice(0, 10) || '尚未登入'}`, danger: !row.active || !row.last_login_at || Date.now() - Date.parse(row.last_login_at) > 30 * 86400000, staffId: String(row.id), canEditStaff: row.id !== user()?.id, details: [{ label: '帳號', value: row.username }, { label: '狀態', value: row.active ? '啟用' : '停用' }], chain: [{ label: '員工', value: row.name }, { label: '權限級別', value: row.role === 'admin' ? '管理者' : '員工' }, ...functions.filter(name => canUse(row, name)).map(name => ({ label: '可用功能', value: name }))] })) },
  { id: 'roles', label: '權限級別', ratio: ['admin', 'staff'].filter(role => rows.value.some(row => row.role === role)).length / 2, entries: ['admin', 'staff'].map(role => ({ id: role, label: role === 'admin' ? '管理者' : '員工', sub: `${rows.value.filter(row => row.role === role).length} 位`, chain: [{ label: '權限級別', value: role === 'admin' ? '管理者' : '員工' }, ...rows.value.filter(row => row.role === role).map(row => ({ label: '員工', value: row.name }))] })) },
  { id: 'functions', label: '功能', ratio: functions.filter(name => rows.value.some(row => row.active && canUse(row, name))).length / functions.length, entries: functions.map((name, index) => ({ id: String(index), label: name, sub: `${rows.value.filter(row => row.active && canUse(row, name)).length} 位可用`, chain: [{ label: '功能', value: name }, ...rows.value.filter(row => row.active && canUse(row, name)).map(row => ({ label: '員工', value: row.name }))] })) },
])
const staffSummary = computed(() => [{ label: '員工', value: rows.value.length }, { label: '停用帳號', value: rows.value.filter(row => !row.active).length, danger: true }, { label: '30 天未登入', value: rows.value.filter(row => !row.last_login_at || Date.now() - Date.parse(row.last_login_at) > 30 * 86400000).length, danger: true }, { label: '只有一位管理者', value: Number(rows.value.filter(row => row.active && row.role === 'admin').length === 1), danger: true, description: '停用或離職時沒有人能管理帳號' }])
const columns = [{ key: 'name', title: '姓名' }, { key: 'username', title: '帳號' }, { key: 'role', title: '權限' }, { key: 'active', title: '狀態' }, { key: 'last_login_at', title: '上次登入' }, { key: 'action', title: '操作' }]
async function load() { loading.value = true; try { const [staff, matrix] = await Promise.all([api('/staff'), api('/permission-matrix')]); rows.value = staff; permissions.value = matrix; error.value = '' } catch (cause) { error.value = cause.message; emit('error', cause) } finally { loading.value = false } }
onMounted(load)
async function create() { busy.value = true; try { await api('/staff', 'POST', form.value); open.value = false; form.value = { name: '', username: '', password: '', role: 'staff' }; await load(); emit('saved', '員工已新增') } catch (cause) { error.value = cause.message; emit('error', cause) } finally { busy.value = false } }
async function update(row, change) { busy.value = true; try { await api(`/staff/${row.id}`, 'PATCH', change); await load(); emit('saved', '員工資料已更新') } catch (cause) { error.value = cause.message; emit('error', cause) } finally { busy.value = false } }
function panoramaAction(id, action) { const row = rows.value.find(item => String(item.id) === id); if (!row || row.id === user()?.id && action === 'active') return; if (action === 'active') update(row, { active: !row.active }); else update(row, { role: row.role === 'admin' ? 'staff' : 'admin' }) }
async function reset() { busy.value = true; try { await api(`/staff/${target.value.id}/reset-password`, 'POST', { password: password.value }); passwordOpen.value = false; password.value = ''; emit('saved', '密碼已重設；原有登入已失效') } catch (cause) { error.value = cause.message; emit('error', cause) } finally { busy.value = false } }
</script>
<template>
  <section class="panel"><div class="panel-head"><div><h2>員工</h2><p>管理者可新增帳號、設定權限及停用離職員工。</p></div><Button variant="primary" @click="open = true">＋ 新增員工</Button></div><Segmented v-model="staffView" :options="[{ value: 'table', label: '表格' }, { value: 'panorama', label: '全景' }]" label="員工視圖" /><p v-if="error" role="alert">{{ error }} <Button @click="load">重試</Button></p><PanoramaGraph v-if="staffView === 'panorama'" title="權限全景" :categories="staffCategories" :summary="staffSummary" @staff-action="panoramaAction" @staff="id => { target = rows.find(row => String(row.id) === id); if (target) passwordOpen = true }" /><DataTable v-else :columns="columns" :data="rows" :loading="loading" :min-width="760" empty-text="尚無員工，請新增員工帳號"><template #cell-role="{ row }"><select :value="row.role" :disabled="busy || row.id === user()?.id" :aria-label="`${row.name}權限`" @change="update(row, { role: $event.target.value })"><option value="admin">管理者</option><option value="staff">員工</option></select></template><template #cell-active="{ row }"><Tag :tone="row.active ? 'ok' : 'neutral'">{{ row.active ? '啟用' : '停用' }}</Tag></template><template #cell-last_login_at="{ row }">{{ row.last_login_at ? row.last_login_at.slice(0, 16).replace('T', ' ') : '尚未登入' }}</template><template #cell-action="{ row }"><div class="row-actions"><span v-if="row.id === user()?.id" class="cell-sub">（你自己）</span><button v-else class="text-button" :disabled="busy" @click="update(row, { active: !row.active })">{{ row.active ? '停用' : '啟用' }}</button><button class="text-button" @click="target = row; passwordOpen = true">重設密碼</button></div></template></DataTable></section>
  <Modal :open="open" title="新增員工" @close="open = false"><Field label="姓名" required><TextInput v-model="form.name" /></Field><Field label="登入帳號" required><TextInput v-model="form.username" /></Field><Field label="初始密碼（至少 10 個字元）" required><TextInput v-model="form.password" type="password" /></Field><Field label="權限"><select v-model="form.role"><option value="staff">員工</option><option value="admin">管理者</option></select></Field><p v-if="error" role="alert">{{ error }}</p><template #footer><Button @click="open = false">取消</Button><Button variant="primary" :disabled="busy || !form.name.trim() || !form.username.trim() || form.password.length < 10" @click="create">新增</Button></template></Modal>
  <Modal :open="passwordOpen" :title="`重設${target?.name || ''}的密碼`" @close="passwordOpen = false"><Field label="新密碼（至少 10 個字元）" required><TextInput v-model="password" type="password" /></Field><p v-if="error" role="alert">{{ error }}</p><template #footer><Button @click="passwordOpen = false">取消</Button><Button variant="primary" :disabled="busy || password.length < 10" @click="reset">重設</Button></template></Modal>
</template>
